insert into public.profiles(id,data,sort_order,is_visible) values('00000000-0000-4000-8000-000000000001','{"first_name":"Matias Andres","last_name":"Meneclier","age":21,"nationality":"Argentino","short_location":"Buenos Aires, Argentina","location":"Buenos Aires, Provincia de Buenos Aires, Argentina","headline":"Estudiante de Ingeniería Informática | Programación | Arquitectura de Computadoras | Sistemas | Interés en desarrollo de software y tecnología","degree":"Ingeniería Informática","university":"Facultad de Ingeniería del Ejército","photo":"","bio":"Estudiante de Ingeniería Informática con interés en programación, arquitectura de computadoras, sistemas y desarrollo de software.","about_caption":"Del hardware al software.\nDe la curiosidad a la práctica.","about_title":"Entender cómo funciona.\nConstruir lo que sigue.","about":"Soy estudiante de Ingeniería Informática con gran interés en el funcionamiento interno de las computadoras, la programación y los sistemas tecnológicos.\n\nActualmente me encuentro desarrollando mis conocimientos en áreas como programación, arquitectura de computadoras y electrónica, buscando siempre comprender cómo funcionan los sistemas desde lo más fundamental hasta su aplicación práctica.\n\nMe interesa participar en proyectos que me permitan seguir aprendiendo, enfrentar desafíos técnicos y trabajar en equipo para desarrollar soluciones tecnológicas.\n\nEstoy abierto a oportunidades de aprendizaje, colaboración y desarrollo profesional en el área de tecnología.","email":"","phone":"","linkedin":"https://www.linkedin.com/in/matias-meneclier-9bb8a83b6/","github":"https://github.com/MatiasMeneclier","instagram":"https://www.instagram.com/matimene_/","cv":"","headline_en":"Computer Engineering student | Programming, Computer Architecture and Systems | Exploring software development","degree_en":"Computer Engineering","bio_en":"Computer Engineering student interested in programming, computer architecture, systems and software development.","about_title_en":"Understand the foundations.\nBuild what comes next.","about_caption_en":"From hardware to software.\nFrom curiosity to practice.","about_en":"I am a Computer Engineering student with a curiosity for how computers work, from the underlying hardware to the software and systems built on top of it.\n\nI am building my knowledge of programming, computer architecture and electronics, connecting fundamental concepts with practical applications.\n\nI am looking to contribute to projects where I can keep learning, solve technical problems and collaborate with a team.\n\nI welcome opportunities to learn, collaborate and grow professionally in technology."}'::jsonb,0,true) on conflict(id) do nothing;
insert into public.site_settings(id,data,sort_order,is_visible) values('00000000-0000-4000-8000-000000000002','{"hero_statement":"Software.\nSistemas.\nPosibilidades.","hero_name":"MATIAS","hero_surname":"MENECLIER","intro_title":"MATIAS MENECLIER","hero_subtitle":"Software Engineering Student","hero_description":"Estudiante de Ingeniería Informática con interés en programación, arquitectura de computadoras, sistemas y desarrollo de software.","projects_title":"Ideas que toman forma.","projects_empty_title":"Próximos proyectos","projects_empty":"Un espacio para compartir lo que voy construyendo.","gallery_title":"Más allá del código.","gallery_empty":"Nuevas imágenes, próximamente.","contact_title":"La próxima idea empieza con una conversación.","experience_title":"Experiencia que suma.","education_title":"Bases sólidas.\nAprendizaje continuo.","skills_title":"Un toolkit en evolución.","theme":"Soft","primary":"#f5f5f7","secondary":"#a1a1aa","accent":"#a8c4e6","background":"#08090b","typography":"Inter","radius":16,"animation_intensity":"Full","intro_enabled":true,"terminal_enabled":true,"contact_enabled":true,"footer":"Matias Meneclier · Buenos Aires, Argentina","dark_enabled":true,"soft_enabled":true,"soft_background":"#f8f7f3","soft_primary":"#202126","soft_secondary":"#62616b","soft_accent":"#685487","hero_statement_en":"Software.\nSystems.\nPossibilities.","hero_description_en":"Computer Engineering student exploring programming, computer architecture and systems, with a focus on software development.","projects_title_en":"Ideas taking shape.","projects_empty_title_en":"Projects coming soon","projects_empty_en":"A space for the things I am building.","gallery_title_en":"Beyond the code.","gallery_empty_en":"New images coming soon.","contact_title_en":"The next idea starts with a conversation.","experience_title_en":"Experience that adds perspective.","education_title_en":"Strong foundations.\nContinuous learning.","skills_title_en":"An evolving toolkit.","hero_